exportRecipes.export-more-guests.mjs:
import {readFileSync,writeFileSync} from 'node:fs';
import {compileDecisionScripts,readDecisionSources} from '@wildshard/sharddev/buildDecisionScripts';
import {compileReturnProjectionV2} from '@wildshard/sharddev/returnProjectionV2';
import {nalatiRidingRows} from '<checkouts>/shard-nalati/src/generators/ridingRows.mjs';
import {NALATI_ECOLOGY} from '<checkouts>/shard-nalati/src/generators/ecology.mjs';
import {nalatiChargeRows} from '<checkouts>/shard-nalati/src/generators/chargeRows.ts';
import {DRIFTWOOD_RETURN_FIELDS as fields,DRIFTWOOD_RETURN_CHANNELS as channels,DRIFTWOOD_RETURN_SIGNALS as signals} from '<checkouts>/shard-driftwood/src/generators/guestPrograms.ts';
const nalati='<checkouts>/shard-nalati';
const riding=await nalatiRidingRows(compileReturnProjectionV2,name=>readFileSync(nalati+'/src/'+name,'utf8'),NALATI_ECOLOGY);
const base64=bytes=>Buffer.from(bytes).toString('base64');
writeFileSync('tmp/codex-tc48/riding.json',JSON.stringify({programs:riding.programs,wasm:base64(riding.wasm),witness:base64(riding.witness)}));
const charge=await nalatiChargeRows(compileDecisionScripts,readDecisionSources(nalati+'/src'));
writeFileSync('tmp/codex-tc48/charge.json',JSON.stringify({rows:charge.rows,wasm:base64(charge.wasm)}));
const aliases=names=>Object.fromEntries(names.map(name=>[name,name]));
const registry=names=>new Map([...names].sort().map((name,i)=>[name,i+1]));
const input={id:'driftwood.returns',abi:'1.0',side:'sim',module:`blobs/wasm/${'0'.repeat(64)}.wasm`,source:'behaviour/returns.as',binding:{shard:true},pages:1,onFail:'hold',on:['signal'],tick:null,stateVersion:1,state:[],params:{},reads:['field','random','groundHeight','radial'],commands:['channel'],fields:aliases(fields),channels:aliases(channels),signals:aliases(signals)};
const registries={fields:registry(fields),channels:registry(channels),signals:registry(signals)};
const built=await compileDecisionScripts([input],registries,readDecisionSources('<checkouts>/shard-driftwood/src'),{asLineCeiling:1716});
const RETURN_PROGRAM={script:built.rows[0],bytes:''};
writeFileSync('test/fixtures/frozen/returns.json',JSON.stringify({...RETURN_PROGRAM,bytes:base64(built.blobs[0].bytes)})+'\n');

{
  const declaration = { ...RETURN_PROGRAM.script, id: 'saltmarsh.returns', source: 'behaviour/marsh.as' };
  const built = await compileDecisionScripts([declaration], {
    fields: new Map(Object.values(declaration.fields).sort().map((name, i) => [name, i + 1])),
    channels: new Map(Object.values(declaration.channels).sort().map((name, i) => [name, i + 1])),
    signals: new Map(Object.values(declaration.signals).sort().map((name, i) => [name, i + 1])),
  }, new Map([['behaviour/marsh.as', "import { Read, Do, Channel, Signal } from './generated/saltmarshReturns';\n@inline export function onSignal(signal:i32,value:f64,source:i32):void { const draw=Read.random(); if(signal==Signal.schedule){Do.channel(Channel.due,7+draw);return;} Do.channel(Channel.x,draw); unreachable(); }"]]), { asLineCeiling: 10 });

writeFileSync('test/fixtures/frozen/saltmarsh-returns.json',JSON.stringify({script:built.rows[0],bytes:base64(built.blobs[0].bytes)})+'\n');
}

{
  const declaration = { ...RETURN_PROGRAM.script, id: 'marsh.returns', source: 'behaviour/marsh.as' };
  const built = await compileDecisionScripts([declaration], {
    fields: new Map(Object.values(declaration.fields).sort().map((name, i) => [name, i + 1])),
    channels: new Map(Object.values(declaration.channels).sort().map((name, i) => [name, i + 1])),
    signals: new Map(Object.values(declaration.signals).sort().map((name, i) => [name, i + 1])),
  }, new Map([['behaviour/marsh.as', `import { Read, Do, Field, Channel, Signal } from './generated/marshReturns';
@inline export function onSignal(signal:i32,value:f64,source:i32):void {
  if(signal==Signal.schedule) Do.channel(Channel.due,Read.field(0,Field.now)+Read.field(0,Field.minimum));
  if(signal==Signal.eligible) Do.channel(Channel.eligible,Read.field(0,Field.now)>=Read.field(0,Field.due)&&Read.field(0,Field.playerX)>10?1:0);
  if(signal==Signal.place) { Do.channel(Channel.x,Read.field(0,Field.x)+2); Do.channel(Channel.z,Read.field(0,Field.z)-1); Do.channel(Channel.retry,0); }
}`]]), { asLineCeiling: 10 });

writeFileSync('test/fixtures/frozen/marsh-returns.json',JSON.stringify({script:built.rows[0],bytes:base64(built.blobs[0].bytes)})+'\n');
}

